import React, { useEffect, useState } from 'react';
import axios from 'axios';

function Admin() {
  const [users, setUsers] = useState([]);
  const [malwareScans, setMalwareScans] = useState([]);
  const [vulnScans, setVulnScans] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchUsers = async () => {
    setError(null);
    setLoading(true);
    try {
      const res = await axios.get('/api/auth/admin/users');
      setUsers(res.data.users || []);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  const fetchMalwareScans = async () => {
    try {
      const res = await axios.get('/api/malware/history');
      setMalwareScans(res.data.history || []);
    } catch (err) {
      console.error('Failed to load malware scans');
    }
  };

  const fetchVulnScans = async () => {
    try {
      const res = await axios.get('/api/vuln/history');
      setVulnScans(res.data.history || []);
    } catch (err) {
      console.error('Failed to load vuln scans');
    }
  };

  useEffect(() => {
    fetchUsers();
    fetchMalwareScans();
    fetchVulnScans();
  }, []);

  return (
    <div className="container-fluid">
      <div className="row">
        <div className="col-12">
          <h2>Admin Panel</h2>
          {error && <div className="alert alert-danger">{error}</div>}
        </div>
      </div>

      <div className="row mb-4">
        <div className="col-lg-4 col-md-6">
          <div className="card bg-dark text-white h-100">
            <div className="card-body">
              <h5 className="card-title">Users ({users.length})</h5>
              {loading ? (
                <p>Loading...</p>
              ) : (
                <div className="table-responsive">
                  <table className="table table-sm table-dark table-striped">
                    <thead>
                      <tr>
                        <th>Username</th>
                        <th>Role</th>
                        <th>Tenant</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map((u) => (
                        <tr key={u.id}>
                          <td>{u.username}</td>
                          <td>{u.role}</td>
                          <td>{u.tenant_id}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="col-lg-4 col-md-6">
          <div className="card bg-dark text-white h-100">
            <div className="card-body">
              <h5 className="card-title">Malware Scans ({malwareScans.length})</h5>
              <div className="table-responsive">
                <table className="table table-sm table-dark table-striped">
                  <thead>
                    <tr>
                      <th>File</th>
                      <th>Status</th>
                      <th>Scanned At</th>
                    </tr>
                  </thead>
                  <tbody>
                    {malwareScans.slice(0, 10).map((s) => (
                      <tr key={s.id}>
                        <td className="text-break">{s.filename}</td>
                        <td>
                          <span
                            className={
                              s.status === 'MALICIOUS'
                                ? 'text-danger'
                                : s.status === 'SUSPICIOUS'
                                ? 'text-warning'
                                : 'text-success'
                            }
                          >
                            {s.status}
                          </span>
                        </td>
                        <td>{new Date(s.scanned_at).toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>

        <div className="col-lg-4 col-md-12">
          <div className="card bg-dark text-white h-100">
            <div className="card-body">
              <h5 className="card-title">Vuln Scans ({vulnScans.length})</h5>
              <div className="table-responsive">
                <table className="table table-sm table-dark table-striped">
                  <thead>
                    <tr>
                      <th>URL</th>
                      <th>Scanned At</th>
                    </tr>
                  </thead>
                  <tbody>
                    {vulnScans.slice(0, 10).map((s) => (
                      <tr key={s.id}>
                        <td className="text-break">{s.url}</td>
                        <td>{new Date(s.scanned_at).toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-12">
          <div className="card bg-dark text-white">
            <div className="card-body">
              <h5 className="card-title">System Features</h5>
              <ul className="list-group list-group-flush">
                <li className="list-group-item bg-dark text-white">✅ Scheduled scan jobs (APScheduler)</li>
                <li className="list-group-item bg-dark text-white">✅ Alerting / notification (email/Slack)</li>
                <li className="list-group-item bg-dark text-white">✅ Multi-tenant dashboard</li>
                <li className="list-group-item bg-dark text-white">✅ Advanced OWASP Top 10 scan coverage (SSRF / RCE detection)</li>
                <li className="list-group-item bg-dark text-white">✅ Admin panel UI for user + scan management</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Admin;
